cd "/c/Users/ryanf/AppData/Local/Temp/pixl readiness claude clean fg97pmgn/consumer" && "/c/github/pixel-lab-agent/build/readiness-setup-01/runtime/Scripts/python.exe" -I - <<'EOF'
import json
root="work/consumer-execution/execution-01/"
a=json.load(open(root+"result.json",encoding="utf-8")); b=json.load(open("work/consumer-execution/execution-result.json",encoding="utf-8"))
print("keys only in attempt:",sorted(set(a)-set(b))); print("keys only in export:",sorted(set(b)-set(a)))
for k in sorted(set(a)&set(b)):
    if a[k]!=b[k]: print("DIFF",k,":",json.dumps(a[k])[:300],"||",json.dumps(b[k])[:300])
print("=====VIEWS")
c=json.load(open(root+"capture/capture.json",encoding="utf-8"))
for v in c["views"]:
    d=v["descriptor"]; im=v["image"]
    print(f'{v["consumer"]:14}{v["state"]:10}x{v["scale"]} motion={d.get("motion")} animate={d.get("animate")} hold={d.get("holdFrame")} label={d.get("label")} frame={v.get("frame")} expected={v.get("expectedFrame")} geom={v.get("geometryMatches")} img={im["path"]} {im["sha256"][:16]} {im.get("width")}x{im.get("height")}')
print("=====PHASES summary")
for p in c["phases"]:
    keys=[k for k in p if k not in("samples","counts")]
    print({k:p[k] for k in keys if k not in ("switches","reconciliations","paintLog")})
    for name in ("samples","switches","reconciliations"):
        if name in p: print("  ",name,"len",len(p[name]) if isinstance(p[name],list) else p[name])
    # print first sample of a 'samples' with image path
    s=p.get("samples")
    if s: print("   first sample:",json.dumps(s[0])[:700])
EOF
echo "=====executables.json"; cat "work/consumer-execution/execution-01/execution/executables.json"; echo; echo "=====launch.json (head)"; head -c 1500 "work/consumer-execution/execution-01/capture/launch.json"; echo; echo "=====observation.json (head)"; head -c 1500 "work/consumer-execution/execution-01/observation.json"; echo; echo "=====execution/*.json"; for f in node-version node-capabilities capture check observation; do echo "--$f"; head -c 700 "work/consumer-execution/execution-01/execution/$f.json"; echo; done

cd "/c/Users/ryanf/AppData/Local/Temp/pixl readiness claude clean fg97pmgn/consumer" && "/c/github/pixel-lab-agent/build/readiness-setup-01/runtime/Scripts/python.exe" -I - <<'EOF'
import json
root="work/consumer-execution/execution-01/"
c=json.load(open(root+"capture/capture.json",encoding="utf-8"))
print("views count",len(c["views"]))
for v in c["views"][12:]:
    d=v["descriptor"]; im=v["image"]
    print(f'{v["consumer"]:14}{v["state"]:10}x{v["scale"]} motion={d.get("motion")} animate={d.get("animate")} hold={d.get("holdFrame")} label={d.get("label")} frame={v.get("frame")} img={im["path"]} {im["sha256"][:16]}')
print("=====PHASE meta")
for p in c["phases"]:
    print({k:(v if not isinstance(v,(list,dict)) else f"<{type(v).__name__} len {len(v)}>") for k,v in p.items()})
    s=p.get("samples") or p.get("cells")
    if isinstance(s,list) and s: print("   sample0:",json.dumps(s[0])[:500])
    for name in ("switches","reconciliations"):
        if isinstance(p.get(name),list) and p[name]: print("  ",name,"0:",json.dumps(p[name][0])[:400])
print("=====MOTION mapping (import result supplied_observations)")
ir=json.load(open(root+"import/result.json",encoding="utf-8"))
fmap={f["id"]:(f["path"].split("/")[-1],f["sha256"]) for f in ir["files"]}
for m in ir["supplied_observations"]["motion"]:
    cells=[(s["frame"],fmap[s["output_id"]][0].replace("cell-","").replace(".png","")) for s in m["samples"]]
    el=[round(s["elapsed_ms"],1) for s in m["samples"]]
    print(m["consumer"],"|",m["mode"],"| n=",len(m["samples"]),"| frame:cell",cells,"| elapsed",el, "| hold" if "hold" in m else "", {k:v for k,v in m.items() if k not in("samples","consumer","mode","limitation","frame_count","frame_ms")})
print("other supplied_observations keys:",[k for k in ir["supplied_observations"] if k!="motion"])
for k in ir["supplied_observations"]:
    if k!="motion": print(k,":",json.dumps(ir["supplied_observations"][k])[:600])
EOF
echo "=====executables.json"; cat "work/consumer-execution/execution-01/execution/executables.json"; echo; echo "=====launch.json (head)"; head -c 1200 "work/consumer-execution/execution-01/capture/launch.json"; echo; echo "=====browser-process.json"; head -c 800 "work/consumer-execution/execution-01/capture/browser-process.json"; echo; echo "=====execution/*.json"; for f in node-version node-capabilities capture check observation; do echo "--$f"; head -c 600 "work/consumer-execution/execution-01/execution/$f.json"; echo; done

