cd "/c/Users/ryanf/AppData/Local/Temp/pixl readiness claude clean fg97pmgn/consumer" && python -I - <<'EOF'
import json, hashlib, os
r=json.load(open('work/consumer-execution-inputs/restoration.json',encoding='utf-8'))
files=r['original']['files']
print('restoration file entries:',len(files))
print('restoration top keys:',list(r.keys()), 'original keys:', list(r['original'].keys()))
def sha(p):
    h=hashlib.sha256()
    with open(p,'rb') as f:
        for c in iter(lambda:f.read(1<<20),b''): h.update(c)
    return h.hexdigest()
top=[f for f in os.listdir('.') if os.path.isfile(f)]
ok=[];miss=[];bad=[]
for f in top:
    if f in files:
        (ok if sha(f)==files[f] else bad).append(f)
    else: miss.append(f)
print('top-level matched:',len(ok),'mismatch:',bad,'not in restoration manifest:',miss)
# also check how many restoration entries exist and match in general (excluding historical host)
cnt=0;badc=[]
for p,h in files.items():
    if p.startswith('.agents') or p.startswith('.codex'): continue
    if os.path.isfile(p):
        cnt+=1
        if sha(p)!=h: badc.append(p)
print('restoration entries present:',cnt,'mismatched:',badc[:20])
EOF
